            if n % i == 0:
                return False        return True
    @staticmethod
    def fact(N):
        res = {}        tmp = N        for i in range(2, int(N ** 0.5 + 1) + 1):            cnt = 0            while tmp % i == 0:                cnt += 1                tmp //= i            if cnt > 0:                res[i] = cnt        if tmp != 1:            res[tmp] = 1        if res == {}:
            res[N] = 1
        return res
