        u, v = v, u
    u %= MOD
    if u < 0:
        u += MOD
    return u
def factorial(N):

    if N == 0 or N == 1:

        return 1

    res = N

    for i in range(N - 1, 1, -1):

        res *= i

        res %= MOD

    return res
